insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  22,
  $wyb$A monthly reporting pipeline that ingests a transactions CSV (QuickBooks/Xero export), cleans and categorizes it, computes core metrics (revenue, expenses, margin, MoM growth, runway) with every division guarded against a zero denominator, generates charts, flags statistical outlier transactions, asks the AI to write plain-English commentary -- checked for whether it actually references the real numbers -- and assembles everything into a polished PDF.$wyb$,
  $wyl$[
  "Standardize a financial CSV export whose column names vary by tool, with type coercion tested against real edge-case data",
  "Guard every division in a financial calculation against a zero denominator, instead of trusting the data is always well-behaved",
  "Generate matplotlib charts and close their figures properly so they don't corrupt a later PDF embed",
  "Check whether AI-written commentary actually references the real computed numbers, not just plausible-sounding prose",
  "Detect statistical outlier transactions with a minimum-sample-size guard, so a brand-new category doesn't get falsely flagged",
  "Assemble a multi-section PDF report with reportlab"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.6 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "135 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A sample transactions CSV (export one from QuickBooks/Xero, or use your own bank export)",
    "Your current cash balance (for the runway calculation)"
  ],
  "outcomes": [
    "Ingest and clean a QuickBooks/Xero-style transactions CSV, with type coercion tested against real edge cases",
    "Compute revenue, expenses, margin, MoM growth, and cash runway, with every division guarded against a zero denominator",
    "Generate revenue and expense charts, properly closed so they never corrupt a later PDF embed",
    "Have the AI write plain-English commentary, checked for whether it actually references the real numbers",
    "Flag statistical outlier transactions without false-flagging a brand-new category with too little data",
    "Assemble everything into a polished, multi-section PDF report"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Ingest and clean your transactions",
      "time": "30 min",
      "description": "Get a clean, standardized DataFrame before computing anything.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# Overridable via .env if you ever want to try a different model.\nGEMINI_MODEL = os.environ.get(\"GEMINI_MODEL\", \"gemini-2.5-flash\")\nGEMINI_URL = (\n    f\"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent\"\n)\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(\n                GEMINI_URL, params={\"key\": api_key}, json=payload, timeout=90\n            )\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            last_problem = \"Gemini is busy (503 - high demand on the free tier)\"\n            time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n    raise AIError(\n        f\"Gemini was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with this content, then replace the placeholders with your real keys:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Open your transactions CSV and note the actual column names - they vary by export tool (e.g. \"Transaction Date\" vs \"Date\", \"Amount\" vs \"Net Amount\").",
          "verify": "Write down the exact column names you see - you'll edit COLUMN_MAP in the next step to match them."
        },
        {
          "instruction": "Create `ingest.py` with this code, then edit COLUMN_MAP at the top to match YOUR CSV's actual column names:",
          "prompt": "\"\"\"\nStep 1 of the Financial Reporting Agent (part 1).\n\nReads a transactions CSV and standardizes it, since column names vary\nwildly by export tool (\"Transaction Date\" vs \"Date\", \"Amount\" vs \"Net\nAmount\"). The column-mapping and type-coercion logic is tested below\nagainst a real pandas DataFrame, not mocked data.\n\"\"\"\n\nimport pandas as pd\n\n# Edit this to match YOUR export's actual column names on the left.\n# Open your CSV first and check - QuickBooks, Xero, and a raw bank\n# export all name these differently.\nCOLUMN_MAP = {\n    \"Transaction Date\": \"date\",\n    \"Amount\": \"amount\",\n    \"Category\": \"category\",\n    \"Description\": \"description\",\n}\n\n\ndef standardize_columns(df, column_map=COLUMN_MAP):\n    \"\"\"\n    Renames df's columns via column_map, converts date to datetime and\n    amount to numeric (invalid values become NaT/NaN rather than\n    raising), and drops rows where amount couldn't be parsed at all.\n\n        standardize_columns(raw_df)\n\n    Kept separate from the actual file read (load_transactions, below)\n    so this can be tested against a DataFrame you build directly in\n    Python, without needing a real CSV file on disk.\n    \"\"\"\n    df = df.rename(columns=column_map)\n    df[\"date\"] = pd.to_datetime(df[\"date\"], errors=\"coerce\")\n    df[\"amount\"] = pd.to_numeric(df[\"amount\"], errors=\"coerce\")\n\n    before = len(df)\n    df = df.dropna(subset=[\"amount\"])\n    dropped = before - len(df)\n    if dropped:\n        print(f\"Dropped {dropped} row(s) where amount could not be parsed as a number.\")\n\n    return df\n\n\ndef load_transactions(path, column_map=COLUMN_MAP):\n    \"\"\"Reads path as a CSV and returns the standardized DataFrame.\"\"\"\n    df = pd.read_csv(path)\n    return standardize_columns(df, column_map)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check standardize_columns() works - a\n    # real pandas DataFrame built in memory, no CSV file needed:\n    #     python ingest.py\n    raw = pd.DataFrame({\n        \"Transaction Date\": [\"2026-08-01\", \"2026-08-02\", \"not-a-date\"],\n        \"Amount\": [\"100.50\", \"not-a-number\", \"-45.00\"],\n        \"Category\": [\"Sales\", \"Sales\", \"Rent\"],\n        \"Description\": [\"Invoice #1\", \"Invoice #2\", \"August rent\"],\n    })\n\n    result = standardize_columns(raw.copy())\n    print(result)\n\n    assert list(result.columns) == [\"date\", \"amount\", \"category\", \"description\"]\n    print(\"\\nColumns correctly renamed via COLUMN_MAP.\")\n\n    assert len(result) == 2  # the \"not-a-number\" amount row got dropped\n    print(\"Row with an unparseable amount correctly dropped - 2 of 3 rows remain.\")\n\n    remaining_dates = result[\"date\"].tolist()\n    assert pd.isna(remaining_dates[-1])\n    print(\"A row with a bad date but a valid amount is KEPT (date becomes NaT), not dropped -\")\n    print(\"this project only requires amount to be usable, since that's what every metric needs.\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python ingest.py`. You should see columns correctly renamed via COLUMN_MAP, a row with an unparseable amount correctly dropped, and a row with a bad date but a valid amount correctly kept (not dropped) - ending with `All checks passed.`"
        },
        {
          "instruction": "Create `clean.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Financial Reporting Agent (part 2) - normalizes category\nnames and removes duplicate transactions.\n\"\"\"\n\nimport pandas as pd\n\n\ndef clean_transactions(df):\n    \"\"\"\n    Fills missing categories with \"Uncategorized\", title-cases and\n    strips category names (so \" sales\", \"Sales\", and \"SALES\" all become\n    the same \"Sales\" rather than three separate categories), drops\n    duplicate transactions (same date+amount+description), and adds a\n    \"month\" column.\n\n        clean_transactions(df)\n\n    Tested below with a real DataFrame built in memory.\n    \"\"\"\n    df = df.copy()\n\n    df[\"category\"] = df[\"category\"].fillna(\"Uncategorized\").astype(str).str.strip().str.title()\n\n    before = len(df)\n    df = df.drop_duplicates(subset=[\"date\", \"amount\", \"description\"])\n    dropped = before - len(df)\n    if dropped:\n        print(f\"Dropped {dropped} duplicate transaction(s).\")\n\n    df[\"month\"] = df[\"date\"].dt.to_period(\"M\")\n\n    return df\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the cleaning logic works - a\n    # real pandas DataFrame built in memory, no CSV file needed:\n    #     python clean.py\n    df = pd.DataFrame({\n        \"date\": pd.to_datetime([\"2026-08-01\", \"2026-08-01\", \"2026-08-02\"]),\n        \"amount\": [100.0, 100.0, -50.0],\n        \"category\": [\" sales\", \"Sales\", None],\n        \"description\": [\"Invoice #1\", \"Invoice #1\", \"Rent\"],\n    })\n\n    result = clean_transactions(df)\n    print(result)\n\n    assert len(result) == 2  # the exact-duplicate row (same date+amount+description) is dropped\n    print(\"\\nExact-duplicate transaction correctly dropped - 2 of 3 rows remain.\")\n\n    assert set(result[\"category\"]) == {\"Sales\", \"Uncategorized\"}\n    print(\"Category names correctly normalized (' sales' and 'Sales' both became 'Sales'),\")\n    print(\"and a missing category correctly became 'Uncategorized'.\")\n\n    assert \"month\" in result.columns\n    print(\"'month' column correctly added.\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python clean.py`. You should see an exact-duplicate transaction correctly dropped, inconsistent category casing correctly normalized to one value, a missing category correctly filled with 'Uncategorized', and a 'month' column correctly added - ending with `All checks passed.`"
        },
        {
          "instruction": "Now run both on your real CSV:",
          "prompt": "python -c \"from ingest import load_transactions; from clean import clean_transactions; df = clean_transactions(load_transactions('transactions.csv')); print(df.head()); print(df['category'].unique())\"",
          "verify": "Categories should look consistent (no duplicates differing only by case/whitespace), and the row count should be lower than your raw CSV if it had duplicates."
        }
      ],
      "goFurther": "Check df['month'].unique() - confirm you have at least 2 months of data, since MoM growth needs a previous month to compare against."
    },
    {
      "number": 2,
      "title": "Compute core financial metrics",
      "time": "30 min",
      "description": "Turn raw transactions into the numbers a CFO actually cares about - with every division guarded against a zero denominator, since a $0-revenue month or a break-even month is a real, not-rare case in transaction data.",
      "steps": [
        {
          "instruction": "Create `metrics.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the Financial Reporting Agent - turns raw transactions into\nthe numbers a CFO actually cares about. Every division here is guarded\nagainst a zero denominator, since a $0-revenue month or a break-even\nmonth is a real, not-rare case in transaction data, and a raw\nZeroDivisionError (or a silently wrong infinite/NaN percentage) is worse\nthan an honest, capped number.\n\"\"\"\n\n\ndef compute_metrics(df, cash_balance):\n    \"\"\"\n    Groups df by month and returns:\n\n        {\"revenue\": ..., \"expenses\": ..., \"margin\": ..., \"mom_growth\": ...,\n         \"runway_months\": ...}\n\n    for the LATEST month in the data.\n\n        compute_metrics(df, cash_balance=50000)\n\n    Guards three separate divide-by-zero risks:\n      - mom_growth: divides by the PREVIOUS month's revenue\n      - margin: divides by the CURRENT month's revenue\n      - runway_months: divides by burn (expenses - revenue); if burn is\n        zero or negative (breaking even or profitable), runway is\n        reported as None (\"not burning cash\") rather than infinity or\n        a crash.\n    \"\"\"\n    monthly_revenue = df[df[\"amount\"] > 0].groupby(\"month\")[\"amount\"].sum()\n    monthly_expenses = df[df[\"amount\"] < 0].groupby(\"month\")[\"amount\"].sum().abs()\n\n    months = sorted(set(monthly_revenue.index) | set(monthly_expenses.index))\n    if not months:\n        raise ValueError(\"No transactions with a valid month found - nothing to report on.\")\n\n    latest = months[-1]\n    revenue = float(monthly_revenue.get(latest, 0))\n    expenses = float(monthly_expenses.get(latest, 0))\n\n    margin = (revenue - expenses) / max(revenue, 1) * 100\n\n    if len(months) >= 2:\n        previous = months[-2]\n        prev_revenue = float(monthly_revenue.get(previous, 0))\n        mom_growth = (revenue - prev_revenue) / max(prev_revenue, 1) * 100\n    else:\n        mom_growth = None  # no prior month to compare against - be honest about that, don't fake a 0%\n\n    burn = expenses - revenue\n    runway_months = cash_balance / burn if burn > 0 else None\n\n    return {\n        \"revenue\": revenue,\n        \"expenses\": expenses,\n        \"margin\": margin,\n        \"mom_growth\": mom_growth,\n        \"runway_months\": runway_months,\n    }\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check every divide-by-zero guard\n    # actually holds - real pandas DataFrames built in memory, no CSV\n    # file needed:  python metrics.py\n    import pandas as pd\n\n    print(\"Checking a normal two-month case with growth...\")\n    df = pd.DataFrame({\n        \"date\": pd.to_datetime([\"2026-07-01\", \"2026-07-15\", \"2026-08-01\", \"2026-08-15\"]),\n        \"amount\": [1000.0, -400.0, 1500.0, -400.0],\n        \"category\": [\"Sales\", \"Rent\", \"Sales\", \"Rent\"],\n        \"description\": [\"a\", \"b\", \"c\", \"d\"],\n        \"month\": pd.to_datetime([\"2026-07-01\", \"2026-07-15\", \"2026-08-01\", \"2026-08-15\"]).to_period(\"M\"),\n    })\n    result = compute_metrics(df, cash_balance=10000)\n    assert result[\"revenue\"] == 1500.0\n    assert result[\"mom_growth\"] == 50.0  # (1500-1000)/1000 * 100\n    print(\"  OK -\", result)\n\n    print(\"\\nChecking a $0-revenue month doesn't crash margin or mom_growth...\")\n    zero_revenue_df = pd.DataFrame({\n        \"date\": pd.to_datetime([\"2026-08-01\"]),\n        \"amount\": [-500.0],\n        \"category\": [\"Rent\"],\n        \"description\": [\"a\"],\n        \"month\": pd.to_datetime([\"2026-08-01\"]).to_period(\"M\"),\n    })\n    result = compute_metrics(zero_revenue_df, cash_balance=10000)\n    assert result[\"revenue\"] == 0.0\n    assert result[\"margin\"] == -50000.0  # (0 - 500) / max(0,1) * 100 -- finite, not NaN/crash\n    print(\"  OK - zero revenue produced a finite (if dramatic) margin instead of crashing:\", result[\"margin\"])\n\n    print(\"\\nChecking a single-month DataFrame (no prior month) reports mom_growth as None, not a fake 0%...\")\n    assert result[\"mom_growth\"] is None\n    print(\"  OK\")\n\n    print(\"\\nChecking a profitable month (revenue > expenses, so burn <= 0) reports runway as None, not infinity...\")\n    profitable_df = pd.DataFrame({\n        \"date\": pd.to_datetime([\"2026-08-01\", \"2026-08-02\"]),\n        \"amount\": [2000.0, -500.0],\n        \"category\": [\"Sales\", \"Rent\"],\n        \"description\": [\"a\", \"b\"],\n        \"month\": pd.to_datetime([\"2026-08-01\", \"2026-08-02\"]).to_period(\"M\"),\n    })\n    result = compute_metrics(profitable_df, cash_balance=10000)\n    assert result[\"runway_months\"] is None\n    print(\"  OK - runway_months is None (\\\"not burning cash\\\") rather than float('inf') or a crash\")\n\n    print(\"\\nChecking a real burn produces a finite, sane runway...\")\n    burning_df = pd.DataFrame({\n        \"date\": pd.to_datetime([\"2026-08-01\", \"2026-08-02\"]),\n        \"amount\": [500.0, -1500.0],\n        \"category\": [\"Sales\", \"Payroll\"],\n        \"description\": [\"a\", \"b\"],\n        \"month\": pd.to_datetime([\"2026-08-01\", \"2026-08-02\"]).to_period(\"M\"),\n    })\n    result = compute_metrics(burning_df, cash_balance=10000)\n    assert result[\"runway_months\"] == 10.0  # burn=1000, 10000/1000\n    print(\"  OK - runway_months =\", result[\"runway_months\"])\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python metrics.py`. You should see a normal two-month case with 50% growth computed correctly, a $0-revenue month producing a finite (if dramatic) margin instead of crashing, a single-month case correctly reporting mom_growth as None rather than a fake 0%, a profitable month correctly reporting runway as None rather than infinity, and a real burn producing a sane finite runway - ending with `All checks passed.`"
        },
